import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';const root=new URL('../../dist/assets/',import.meta.url),bundle=readFileSync(new URL('index-gold-upgrade-ui-08.js',root),'utf8'),samples=readFileSync(new URL('audio-samples-07.js',root),'utf8');test('held weapon family reaches deployed audio mapper',()=>{assert.ok(bundle.includes('weaponFamily:t.weaponFamily'));assert.ok(bundle.includes('weaponFamily:n?.family'));for(const family of ['SR','DMR','SG','PISTOL','AR','SMG','LMG'])assert.ok(samples.includes(`family==='${family}'`),family);assert.match(samples,/includes\('awm'\)\)a=\[gun\+'shotgun2\.wav',1\.25,1,0\]/);assert.match(samples,/includes\('lynx'\)\)a=\[gun\+'shotgun2\.wav',1\.625,1,0\]/);assert.match(samples,/includes\('mg3'\)\)a=\[gun\+'auto2\.mp3',1\.05,1,1\]/);});
